// Excerpt from ev42014600.nut's AddPartyNum_Message_Black(_add_num, _aParamID, _ptLock,
// _avatarEnable, _avatarLock, _aLv, _important = false): when _important is true, the
// whole batch of new members is added with the "J_07" important-recruitment jingle.
AddPartyNum_Message_Black <- function ( _add_num, _aParamID, _ptLock, _avatarEnable, _avatarLock, _aLv, _important = false )
{
	if (_important)
	{
		AddPartyNum_Important_Message(_add_num, _aParamID, _ptLock, _avatarEnable, _avatarLock, _aLv);
	}
};
